#include <iostream>
#include <map>
#include <queue>
#include <string>
#include <utility>
#include <vector>

using WordCount = std::pair<std::string, int>;

std::vector<std::string> topKFrequent(const std::vector<std::string>& words, int k) {
    std::map<std::string, int> counts;
    for (const std::string& word : words) {
        counts[word]++;
    }
    // The top of a priority_queue is its "largest" item, so a ranks below b
    // when it has a smaller count, or the same count and a later word.
    auto ranksBelow = [](const WordCount& a, const WordCount& b) {
        return a.second != b.second ? a.second < b.second : a.first > b.first;
    };
    std::priority_queue<WordCount, std::vector<WordCount>, decltype(ranksBelow)> heap(ranksBelow);
    for (const auto& entry : counts) {
        heap.push(entry);
    }
    std::vector<std::string> top;
    for (int i = 0; i < k; i++) {
        top.push_back(heap.top().first);
        heap.pop();
    }
    return top;
}

int main() {
    int n, k;
    std::cin >> n >> k;
    std::vector<std::string> words(n);
    for (int i = 0; i < n; i++) {
        std::cin >> words[i];
    }
    for (const std::string& word : topKFrequent(words, k)) {
        std::cout << word << "\n";
    }
    return 0;
}

