package main

import (
	"container/heap"
	"fmt"
)

type wordCount struct {
	word  string
	count int
}

// wordHeap implements heap.Interface: the biggest count on top, ties in
// alphabetical order.
type wordHeap []wordCount

func (h wordHeap) Len() int { return len(h) }
func (h wordHeap) Less(i, j int) bool {
	if h[i].count != h[j].count {
		return h[i].count > h[j].count
	}
	return h[i].word < h[j].word
}
func (h wordHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *wordHeap) Push(x interface{}) { *h = append(*h, x.(wordCount)) }
func (h *wordHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func topKFrequent(words []string, k int) []string {
	counts := map[string]int{}
	for _, word := range words {
		counts[word]++
	}
	h := wordHeap{}
	for word, count := range counts {
		h = append(h, wordCount{word, count})
	}
	heap.Init(&h)
	top := []string{}
	for i := 0; i < k; i++ {
		top = append(top, heap.Pop(&h).(wordCount).word)
	}
	return top
}

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	words := make([]string, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&words[i])
	}
	for _, word := range topKFrequent(words, k) {
		fmt.Println(word)
	}
}

